public void enterOuterAlt(ParserRuleContext newContext, int altNum) {
    if (_buildParseTrees && _ctx != newContext) {
        ParserRuleContext parent = (ParserRuleContext) _ctx.parent;
        if (parent != null) {
            parent.removeLastChild();
            parent.addChild(newContext);
        }
    }
    _ctx = newContext;
    _ctx.setAltNum(altNum); // Assuming setAltNum is a method in ParserRuleContext
}

public void enterOuterAlt(ParserRuleContext localctx, int altNum) {
    // if we have new localctx, make sure we replace existing ctx
    // that is previous child of parse tree
    if (_buildParseTrees && _ctx != localctx) {
        ParserRuleContext parent = (ParserRuleContext) _ctx.parent;
        if (parent != null) {
            parent.removeLastChild();
            parent.addChild(localctx);
        }
    }
    _ctx = localctx;
    final int alternativeNumber = altNum;
    _ctx.altNum = alternativeNumber;
}

