public String getDOT(DFA dfa, boolean isLexer) {
    if (dfa.s0 == null) return null;

    ST dot = stlib.getInstanceOf("dfa");
    dot.add("name", "DFA" + dfa.decision);
    dot.add("startState", dfa.s0.stateNumber);
    dot.add("rankdir", rankdir);

    // Define stop states
    for (DFAState d : dfa.states.keySet()) {
        if (isStopState(d)) {
            ST st = stlib.getInstanceOf("stopstate");
            st.add("name", "s" + d.stateNumber);
            st.add("label", getStateLabel(d));
            dot.add("states", st);
        } else if (isRegularState(d)) {
            ST st = stlib.getInstanceOf("state");
            st.add("name", "s" + d.stateNumber);
            st.add("label", getStateLabel(d));
            dot.add("states", st);
        }
    }

    for (DFAState d : dfa.states.keySet()) {
        if (d.edges != null) {
            for (int i = 0; i < d.edges.length; i++) {
                DFAState target = d.edges[i];
                if (isValidEdgeTarget(target, i)) {
                    int ttype = i - 1; // we shift up for EOF as -1 for parser
                    String label = isLexer ? "\'" + getEdgeLabel(String.valueOf((char) i)) + "\'" 
                                           : grammar != null ? grammar.getTokenDisplayName(ttype) 
                                               : String.valueOf(ttype);
                    ST st = stlib.getInstanceOf("edge");
                    st.add("label", label);
                    st.add("src", "s" + d.stateNumber);
                    st.add("target", "s" + target.stateNumber);
                    st.add("arrowhead", arrowhead);
                    dot.add("edges", st);
                }
            }
        }
    }

    String output = dot.render();
    return Utils.sortLinesInString(output);
}

private boolean isValidEdgeTarget(DFAState target, int index) {
    return target != null && target.stateNumber != Integer.MAX_VALUE;
}

private boolean isStopState(DFAState state) {
    return state.isAcceptState;
}

private boolean isRegularState(DFAState state) {
    return !state.isAcceptState && state.stateNumber != Integer.MAX_VALUE;
}

public String getDOT(DFA dfa, boolean isLexer) {
    if (dfa.s0 == null) return null;

    ST dot = stlib.getInstanceOf("dfa");
    configureDotHeader(dot, dfa);

    addStopStates(dfa, dot);
    addNonAcceptStates(dfa, dot);
    addEdges(dfa, dot, isLexer);

    String output = dot.render();
    return Utils.sortLinesInString(output);
}

private void configureDotHeader(ST dot, DFA dfa) {
    dot.add("name", "DFA" + dfa.decision);
    dot.add("startState", dfa.s0.stateNumber);
    dot.add("rankdir", rankdir);
}

private void addStopStates(DFA dfa, ST dot) {
    for (DFAState state : dfa.states.keySet()) {
        if (state.isAcceptState) {
            ST st = stlib.getInstanceOf("stopstate");
            st.add("name", "s" + state.stateNumber);
            st.add("label", getStateLabel(state));
            dot.add("states", st);
        }
    }
}

private void addNonAcceptStates(DFA dfa, ST dot) {
    for (DFAState state : dfa.states.keySet()) {
        if (!state.isAcceptState && state.stateNumber != Integer.MAX_VALUE) {
            ST st = stlib.getInstanceOf("state");
            st.add("name", "s" + state.stateNumber);
            st.add("label", getStateLabel(state));
            dot.add("states", st);
        }
    }
}

private void addEdges(DFA dfa, ST dot, boolean isLexer) {
    for (DFAState state : dfa.states.keySet()) {
        if (state.edges != null) {
            for (int i = 0; i < state.edges.length; i++) {
                DFAState target = state.edges[i];
                if (target == null || target.stateNumber == Integer.MAX_VALUE) continue;
                int ttype = i - 1; // we shift up for EOF as -1 for parser
                String label = getEdgeLabel(isLexer, i, ttype);
                ST st = stlib.getInstanceOf("edge");
                st.add("label", label);
                st.add("src", "s" + state.stateNumber);
                st.add("target", "s" + target.stateNumber);
                st.add("arrowhead", arrowhead);
                dot.add("edges", st);
            }
        }
    }
}

private String getEdgeLabel(boolean isLexer, int i, int ttype) {
    if (isLexer) {
        return "\'" + getEdgeLabel(String.valueOf((char) i)) + "\'";
    } else if (grammar != null) {
        return grammar.getTokenDisplayName(ttype);
    }
    return String.valueOf(ttype);
}

