static ATNState stateFactory(int type, int ruleIndex) {
    ATNState s = createState(type);
    if (s == null) {
        String message = String.format(Locale.getDefault(), "The specified state type %d is not valid.", type);
        throw new IllegalArgumentException(message);
    }
    s.ruleIndex = ruleIndex;
    return s;
}

static ATNState createState(int type) {
    switch (type) {
        case ATNState.INVALID_TYPE:
            return null;
        case ATNState.BASIC:
            return new BasicState();
        case ATNState.RULE_START:
            return new RuleStartState();
        case ATNState.BLOCK_START:
            return new BasicBlockStartState();
        case ATNState.PLUS_BLOCK_START:
            return new PlusBlockStartState();
        case ATNState.STAR_BLOCK_START:
            return new StarBlockStartState();
        case ATNState.TOKEN_START:
            return new TokensStartState();
        case ATNState.RULE_STOP:
            return new RuleStopState();
        case ATNState.BLOCK_END:
            return new BlockEndState();
        case ATNState.STAR_LOOP_BACK:
            return new StarLoopbackState();
        case ATNState.STAR_LOOP_ENTRY:
            return new StarLoopEntryState();
        case ATNState.PLUS_LOOP_BACK:
            return new PlusLoopbackState();
        case ATNState.LOOP_END:
            return new LoopEndState();
        default:
            return null;
    }
}

