methods:
protected void look(@NotNull ATNState state,
                    @Nullable ATNState stopState,
                    @Nullable PredictionContext context,
                    @NotNull IntervalSet lookSet,
                    @NotNull Set<ATNConfig> lookBusy,
                    @NotNull BitSet calledRuleStack,
                    boolean seeThruPreds, boolean addEOF) {
    ATNConfig config = new ATNConfig(state, 0, context);
    if (!lookBusy.add(config)) return;

    if (state == stopState) {
        handleStopState(context, addEOF, lookSet);
        return;
    }

    if (state instanceof RuleStopState) {
        handleRuleStopState(context, addEOF, stopState, lookSet, lookBusy, calledRuleStack);
        return;
    }

    processTransitions(state, stopState, context, lookSet, lookBusy, calledRuleStack, seeThruPreds);
}

private void handleStopState(@Nullable PredictionContext context, boolean addEOF, 
                              @NotNull IntervalSet lookSet) {
    if (context == null) {
        lookSet.add(Token.EPSILON);
    } else if (context.isEmpty() && addEOF) {
        lookSet.add(Token.EOF);
    }
}

private void handleRuleStopState(@Nullable PredictionContext context, boolean addEOF, 
                                  @Nullable ATNState stopState, 
                                  @NotNull IntervalSet lookSet, 
                                  @NotNull Set<ATNConfig> lookBusy, 
                                  @NotNull BitSet calledRuleStack) {
    if (context == null) {
        lookSet.add(Token.EPSILON);
    } else if (context.isEmpty() && addEOF) {
        lookSet.add(Token.EOF);
    }

    if (context != PredictionContext.EMPTY) {
        for (int i = 0; i < context.size(); i++) {
            ATNState returnState = atn.states.get(context.getReturnState(i));
            boolean removed = calledRuleStack.get(returnState.ruleIndex);
            try {
                calledRuleStack.clear(returnState.ruleIndex);
                look(returnState, stopState, context.getParent(i), lookSet, lookBusy, calledRuleStack, seeThruPreds, addEOF);
            } finally {
                if (removed) {
                    calledRuleStack.set(returnState.ruleIndex);
                }
            }
        }
    }
}

private void processTransitions(@NotNull ATNState state, @Nullable ATNState stopState,
                                @Nullable PredictionContext context, 
                                @NotNull IntervalSet lookSet, 
                                @NotNull Set<ATNConfig> lookBusy, 
                                @NotNull BitSet calledRuleStack, 
                                boolean seeThruPreds) {
    int numTransitions = state.getNumberOfTransitions();
    for (int i = 0; i < numTransitions; i++) {
        Transition transition = state.transition(i);
        if (transition instanceof RuleTransition) {
            processRuleTransition((RuleTransition) transition, stopState, context, lookSet, lookBusy, calledRuleStack, seeThruPreds);
        } else if (transition instanceof PredicateTransition) {
            processPredicateTransition(transition, stopState, context, lookSet, lookBusy, calledRuleStack, seeThruPreds);
        } else if (transition.isEpsilon()) {
            look(transition.target, stopState, context, lookSet, lookBusy, calledRuleStack, seeThruPreds, addEOF);
        } else if (transition instanceof WildcardTransition) {
            lookSet.addAll(IntervalSet.of(Token.MIN_USER_TOKEN_TYPE, atn.maxTokenType));
        } else {
            addTransitionLabels(transition, lookSet);
        }
    }
}

private void processRuleTransition(RuleTransition transition, @Nullable ATNState stopState,
                                    @Nullable PredictionContext context, 
                                    @NotNull IntervalSet lookSet, 
                                    @NotNull Set<ATNConfig> lookBusy, 
                                    @NotNull BitSet calledRuleStack, 
                                    boolean seeThruPreds) {
    if (calledRuleStack.get(transition.target.ruleIndex)) return;

    PredictionContext newContext = SingletonPredictionContext.create(context, transition.followState.stateNumber);
    try {
        calledRuleStack.set(transition.target.ruleIndex);
        look(transition.target, stopState, newContext, lookSet, lookBusy, calledRuleStack, seeThruPreds, addEOF);
    } finally {
        calledRuleStack.clear(transition.target.ruleIndex);
    }
}

private void processPredicateTransition(Transition transition, @Nullable ATNState stopState,
                                        @Nullable PredictionContext context, 
                                        @NotNull IntervalSet lookSet, 
                                        @NotNull Set<ATNConfig> lookBusy, 
                                        @NotNull BitSet calledRuleStack, 
                                        boolean seeThruPreds) {
    if (seeThruPreds) {
        look(transition.target, stopState, context, lookSet, lookBusy, calledRuleStack, seeThruPreds, addEOF);
    } else {
        lookSet.add(HIT_PRED);
    }
}

private void addTransitionLabels(Transition transition, @NotNull IntervalSet lookSet) {
    IntervalSet labels = transition.label();
    if (labels != null) {
        if (transition instanceof NotSetTransition) {
            labels = labels.complement(IntervalSet.of(Token.MIN_USER_TOKEN_TYPE, atn.maxTokenType));
        }
        lookSet.addAll(labels);
    }
}
